import {readFile,writeFile,readdir} from 'node:fs/promises';
import {resolve,join,dirname,relative} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {auditE4Amendment} from './e4-amendment-audit.mjs';
const root=dirname(fileURLToPath(import.meta.url)),repo=resolve(root,'../../..');
const json=async p=>JSON.parse(await readFile(p,'utf8'));
const sha=x=>createHash('sha256').update(x).digest('hex');
const put=(name,value)=>writeFile(join(root,name),JSON.stringify(value,null,2)+'\n',{flag:'wx'});
const protocol=await json(join(root,'protocol.json'));
const available=await readdir(join(root,'isolation-captures'));
const captures=[];
for(const id of protocol.caseIds){if(!available.includes(id))continue;captures.push({id,...await json(join(root,'isolation-captures',id,'result.json'))});}
const accepted=captures.filter(c=>c.acceptedCapture).map(c=>c.id),unresolved=protocol.caseIds.filter(id=>!accepted.includes(id));
const amendment=await auditE4Amendment(root);
const assessment={schemaVersion:1,kind:'response-only-isolation-evidence-assessment-not-independent-acceptance',revision:protocol.revision,version:'4.4.7',captureAttempts:captures.length,newResponses:accepted.length,captureIntegrityAcceptedCaseIds:accepted,captureIntegrityFailedCaseIds:captures.filter(c=>!c.acceptedCapture).map(c=>c.id),unattemptedCaseIds:protocol.caseIds.filter(id=>!captures.some(c=>c.id===id)),unresolvedCaptureCaseIds:unresolved,semanticReviewPendingCaseIds:protocol.caseIds.filter(id=>id!=='E4'),knownParentSemanticFailureIds:['E4'],independentlyQualifiedNewCases:[],e4Amendment:amendment,totalNativeCaptureAttempts:captures.length+1,totalCaptureIntegrityAccepted:accepted.length+Number(amendment.acceptedCapture),independentReview:'Parent-owned independent synthesis against source and frozen rubrics. Diagnosis records original E4 unqualified; this leaf never self-certifies independent behavior.',reusedIndependentCases:['L3-1','L3-2','L3-3','L6-1','L6-2','L6-3','P10','MT1','MT2','MT3'],qualifiedExistingScope:'Seven original zero-dollar candidate/helper responses preserve existing independent acceptance, plus three mobile corrected-transport responses. Actual captured sent text, exact current relevant source bodies and bound independent decisions are separately checked. No repetition of valid MT1–MT3.',missingReason:'Raw dollar mentions in 40 remaining distinct non-mobile frozen scenarios can select installed native skill prompts. Historical raw-dollar capture integrity does not prove source isolation. One preregistered corrected response per affected scenario supplies only fresh isolation evidence, not repetitions or universal behavior.',transport:'Actual sent turn/start parsed text has zero raw dollars; lossless JSON decoding matches paired legacy instructions, context and request exactly. Global assembled model context remains unexposed.',historicalFailures:'Original B8, MR1–MR3, original G6, E2 pre-response HTTP403 and all earlier failures/protocols remain unchanged. Original isolation E4 also remains unqualified; the separately approved E4-AM1 changes only its omitted predecessor observation, with no identical-input retry.',scopeSeparation:{sourceAdoption:'Parent-owned, pending independent acceptance decisions',fullPackageAcceptance:'Parent-owned; six packages and three generated hosts not certified here',nativeDiscovery:'Separate helper; no installed-host acceptance',closureRuntime:'Separate helper; unknown historical closure acceptance remains unchanged',efficiency:'Inconclusive; 294-run comparison unexecuted; no savings, model reliability or loaded-token claim',installation:'No host installs, registrations or settings changed',publication:'No publication operation from this leaf'},hostReview:'Initial egress rejection retained; one proof-bearing resubmission cited direct user attachment and was approved. Zero model requests before approval.',fourPasses:[{pass:1,finding:'Complete 40-case frozen inventory and corrected manifest; exactly paired historical instructions/requests; real native capture runner with configured controls.'},{pass:2,finding:'Source expert pass separated owning instruction bodies from arbitrary fixture keys, preserved original failures, and verified source-byte reuse for unaffected zero-dollar helpers and mobile correction.'},{pass:3,finding:'Correctness pass verifies actual sent parsed text, lossless decoding, terminal response equality, configured/effective controls, tools/images and runtime SHA256 bindings; independent semantic acceptance explicitly remains parent-owned.'},{pass:4,finding:'Polish pass keeps one concise assessment with measured accepted/unresolved inventory, immutable source/evidence/artifact hashes and success-only verification marker; no scope, policy or efficiency upgrade.'}]};
await put('assessment.json',assessment);
const walk=async dir=>{const all=[];for(const e of await readdir(dir,{withFileTypes:true})){const path=join(dir,e.name);if(e.isDirectory())all.push(...await walk(path));else if(e.isFile()&&e.name!=='artifact-bindings.json'&&e.name!=='promotion-files.json')all.push(path);}return all;};
await put('artifact-bindings.json',{kind:'append-only-leaf-artifact-sha256-bindings',sha256:Object.fromEntries(await Promise.all((await walk(root)).sort().map(async p=>[relative(root,p),sha(await readFile(p))])))});
console.log(JSON.stringify({captureAttempts:captures.length,accepted:accepted.length,unresolved:unresolved.length,totalNativeAttempts:captures.length+1,e4AmendmentCapture:amendment.acceptedCapture,independentAcceptance:'parent-owned; original E4 unqualified'}));
